            "longitude": {
              "type": "string",
              "description": "快递柜经度，用于地图导航。",
              "sampleValue": "121.601990"
            }
          }
        },
        "weatherTip": {
          "type": "string",
          "description": "结合当天天气给出的取件短提示。",
          "sampleValue": "适合步行取件"
        }
      },
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询区县名称。",
            "sampleValue": "当前区县"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "27°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "彩色快递箱图标，适合表达物流信息和取件提醒。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合表达多云或天气速览。"
    }
  ]
}

